import {status,validatePlan,join,refund,cancel,release} from './model.js';
const $=s=>document.querySelector(s), key='countmein-practice-v1';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(t);
const localInput=t=>{const d=new Date(t);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const now=Date.now();
const names=['Riya','Aarav','Sam','Neha','Kabir','Dev','Isha','Aditya'];
const members=n=>names.slice(0,n).map((name,i)=>({id:'seed-'+i,name,refunded:false}));
function seed(){return {user:{id:'me',name:'Utkarsh'},plans:[
{id:'friday-football',title:'Friday night football',location:'Your neighborhood turf',category:'sport',amount:50,target:10,deadline:now+2*864e5,eventAt:now+3*864e5,ownerId:'me',ownerName:'Utkarsh',members:members(7),ledger:[],cancelled:false,released:false},
{id:'weekend-trail',title:'The weekend trail',location:'Meet at the trailhead',category:'outing',amount:30,target:6,deadline:now-864e5,eventAt:now+4*864e5,ownerId:'seed-0',ownerName:'Riya',members:members(6),ledger:[],cancelled:false,released:false},
{id:'badminton-doubles',title:'Badminton & breakfast',location:'The local sports club',category:'sport',amount:40,target:4,deadline:now-36e5,eventAt:now+864e5,ownerId:'seed-1',ownerName:'Aarav',members:[...members(1),{id:'me',name:'Utkarsh',refunded:false}],ledger:[],cancelled:false,released:false}
]}}
let state;try{state=JSON.parse(localStorage.getItem(key));if(!state||!Array.isArray(state.plans)||!state.user)state=seed()}catch{state=seed()}
let filter='all',activeId=null,storageWarning=false;
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{if(!storageWarning){storageWarning=true;toast('Storage unavailable. Changes will last for this session only.')}}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300)}
function modal(html,label='COUNTMEIN'){ $('#modal-content').innerHTML=html;$('#modal-eyebrow').textContent=label;if(!$('#modal').open)$('#modal').showModal() }
function close(){ $('#modal').close();activeId=null }
$('#close-modal').onclick=close;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
$('#modal').addEventListener('close',()=>activeId=null);
function badge(p){const s=status(p);return s==='funded'?(p.released?'Funds collected':'All in · Confirmed'):s==='refundable'?(p.cancelled?'Cancelled · Refunds open':'Refunds open'):`${p.target-p.members.length} spots left`}
function render(){
 const open=state.plans.filter(p=>status(p)==='open').length;
 let held=0,available=0;
 for(const p of state.plans){const m=p.members.find(m=>m.id===state.user.id);if(m&&!m.refunded&&!p.released){held+=p.amount;if(status(p)==='refundable')available+=p.amount}}
 $('#stat-plans').textContent=open;$('#stat-deposits').innerHTML=held+' <small>credits</small>';$('#stat-refunds').innerHTML=available+' <small>credits</small>';$('#profile').textContent=state.user.name.slice(0,1).toUpperCase();
 const plans=state.plans.filter(p=>filter==='all'||status(p)===filter);
 $('#plan-grid').innerHTML=plans.length?plans.map(p=>`<article class="card"><div class="card-art ${esc(p.category)}"><span class="big-symbol" aria-hidden="true">${p.category==='sport'?'◎':p.category==='outing'?'△':'✳'}</span><span class="badge ${status(p)}">${esc(badge(p))}</span><span class="category">${p.category==='sport'?'GAME ON':p.category==='outing'?'OUT & ABOUT':'GOOD COMPANY'}</span></div><div class="card-body"><h3>${esc(p.title)}</h3><div class="meta">${esc(date(p.eventAt))}<br>⌖ ${esc(p.location)}</div><div class="card-progress"><div class="progress-label"><b>${p.members.length} of ${p.target} friends in</b><span>${Math.round(p.members.length/p.target*100)}%</span></div><div class="progress" role="progressbar" aria-label="Spots filled" aria-valuenow="${p.members.length}" aria-valuemin="0" aria-valuemax="${p.target}"><i style="width:${Math.min(100,p.members.length/p.target*100)}%"></i></div></div><div class="card-bottom"><div class="price">${p.amount}<small>demo credits / person</small></div><button data-plan="${esc(p.id)}">${status(p)==='refundable'?'View refund →':status(p)==='funded'?'View plan →':'Count me in →'}</button></div><div class="deadline"><span>${status(p)==='open'?'Closes '+esc(date(p.deadline)):status(p)==='funded'?'Your crew is ready':'No one left out of pocket'}</span><span>↗</span></div></div></article>`).join(''):'<div class="empty">No plans here yet. Start one for your crew.</div>';
 $('[data-filter="'+filter+'"]').classList.add('active');
}
$('#plan-grid').onclick=e=>{const b=e.target.closest('[data-plan]');if(b)showPlan(b.dataset.plan)};
$('.filters').onclick=e=>{if(e.target.dataset.filter){filter=e.target.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.remove('active'));render()}};
function showPlan(id){
 const p=state.plans.find(x=>x.id===id);if(!p)return;activeId=id;
 const s=status(p),m=p.members.find(x=>x.id===state.user.id),owner=p.ownerId===state.user.id;
 let main='';
 if(s==='open'&&!m) main=`<button class="primary" id="join-plan">Join with ${p.amount} demo credits</button>`;
 else if(s==='open')main='<button class="outline" disabled>You’re in ✓</button>';
 else if(s==='refundable'&&m&&!m.refunded)main=`<button class="primary" id="refund-plan">Claim ${p.amount} demo credits</button>`;
 else if(s==='refundable')main=`<button class="outline" disabled>${m?.refunded?'Refund claimed ✓':'No deposit to refund'}</button>`;
 else if(owner&&!p.released)main='<button class="primary" id="release-plan">Collect demo funds</button>';
 else main=`<button class="outline" disabled>${p.released?'Funds collected':'Plan confirmed ✓'}</button>`;
 modal(`<h2>${esc(p.title)}</h2><p>Organized by ${esc(p.ownerName)} · ${esc(p.location)}</p><span class="badge ${s}">${esc(badge(p))}</span><div class="detail-grid"><div><small>YOUR SHARE</small><strong>${p.amount} demo credits</strong></div><div><small>THE CREW</small><strong>${p.members.length} / ${p.target} people</strong></div><div><small>FUNDING CLOSES</small><strong style="font-size:13px">${esc(date(p.deadline))}</strong></div><div><small>THE PLAN STARTS</small><strong style="font-size:13px">${esc(date(p.eventAt))}</strong></div></div><div class="people">${p.members.map(m=>`<span class="person">${esc(m.name)}${m.refunded?' · refunded':''}</span>`).join('')||'<p>Be the first one in.</p>'}</div><div class="notice">${s==='open'?`All ${p.target} spots must be filled before the deadline. Your deposit commits your spot; refunds open only if the plan fails or the organizer cancels it.`:s==='funded'?'The target is reached. Funding is confirmed and the organizer can collect it. This does not guarantee venue booking or delivery.':p.cancelled?'The organizer cancelled. Each participant can claim their own demo deposit.':'The deadline passed without enough people. Each participant can claim their own demo deposit.'}</div><div class="actions">${main}<button class="outline" id="share-plan">Copy invitation</button></div><div class="secondary-actions">${owner&&s==='open'?'<button class="text-button" id="cancel-plan">Cancel plan</button>':'<span></span>'}${s==='open'?'<button class="text-button" id="practice-controls">Practice controls ↗</button>':''}</div><div class="ledger"><b>Practice activity</b>${p.ledger.length?p.ledger.slice(0,5).map(l=>`<div><span>${esc(l.text)}</span><strong>${l.amount>0?'+':''}${l.amount||'—'}</strong></div>`).join(''):'<p>No activity yet. This is a local practice plan.</p>'}</div>`,'PLAN DETAILS · PRACTICE MODE');
 const act=(fn,msg)=>{try{fn();save();render();showPlan(id);toast(msg)}catch(e){toast(e.message)}};
 if($('#join-plan'))$('#join-plan').onclick=()=>modal(`<h2>You’re one step from “I’m in.”</h2><p>Commit ${p.amount} demo credits to ${esc(p.title)} as ${esc(state.user.name)}.</p><div class="notice">You cannot withdraw just because you change your mind. Refunds open if the target is missed at the deadline or the organizer cancels before the plan is full. No real money moves in this version.</div><button id="confirm-join" class="primary full">Confirm demo deposit</button>`,'REVIEW YOUR COMMITMENT')||($('#confirm-join').onclick=()=>act(()=>join(p,state.user),'You’re in. Demo deposit recorded.'));
 if($('#refund-plan'))$('#refund-plan').onclick=()=>act(()=>refund(p,state.user.id),'Your demo deposit has been refunded.');
 if($('#release-plan'))$('#release-plan').onclick=()=>act(()=>release(p,state.user.id),'Demo funds marked collected. No real payment was sent.');
 if($('#cancel-plan'))$('#cancel-plan').onclick=()=>{modal('<h2>Cancel this plan?</h2><p>This opens refunds for every participant. It cannot be undone.</p><button class="primary full" id="confirm-cancel">Cancel plan and open refunds</button>');$('#confirm-cancel').onclick=()=>act(()=>cancel(p,state.user.id),'Plan cancelled. Refunds are open.')};
 $('#share-plan').onclick=async()=>{const text=`Count me in: ${p.title}\n${date(p.eventAt)} · ${p.location}\n${p.amount} demo credits each · ${p.target} spots\nCommit by ${date(p.deadline)}. Full group or refund.\nThis is a practice invitation, not a live payment link.`;try{await navigator.clipboard.writeText(text);toast('Practice invitation copied.')}catch{modal('<h2>Your invitation</h2><p>Copy this practice invitation:</p><textarea readonly style="width:100%;min-height:180px;padding:12px">'+esc(text)+'</textarea>')}};
 if($('#practice-controls'))$('#practice-controls').onclick=()=>{modal('<h2>Try both outcomes.</h2><p>These controls change this browser’s demo only. They do not represent payments or real participants.</p><div class="actions"><button class="primary" id="add-friend">Add a demo friend</button><button class="outline" id="expire-plan">Pass the deadline</button></div>','PRACTICE CONTROLS');$('#add-friend').onclick=()=>act(()=>join(p,{id:crypto.randomUUID(),name:'Demo friend '+(p.members.length+1)}),'A demo friend joined.');$('#expire-plan').onclick=()=>act(()=>{p.deadline=Date.now()-1000},'Deadline passed. Refunds are open.')};
}
function create(){activeId=null;modal(`<h2>What’s the plan?</h2><p>Give your crew a reason to leave the group chat.</p><form id="create-form"><label for="title">Plan name</label><input id="title" name="title" placeholder="Friday night football" maxlength="70" required><div class="row"><div><label for="category">Activity</label><select id="category" name="category"><option value="sport">Sports</option><option value="outing">Outing</option><option value="social">Get-together</option></select></div><div><label for="location">Where?</label><input id="location" name="location" placeholder="Your neighborhood turf" maxlength="90" required></div></div><div class="row"><div><label for="amount">Demo credits per person</label><input id="amount" name="amount" type="number" min="1" max="10000" step="1" value="50" required></div><div><label for="target">People needed (including you)</label><input id="target" name="target" type="number" min="2" max="50" value="10" required></div></div><label for="deadline">Deadline to fill all spots</label><input id="deadline" name="deadline" type="datetime-local" value="${localInput(Date.now()+2*864e5)}" required><label for="eventAt">When’s it happening?</label><input id="eventAt" name="eventAt" type="datetime-local" value="${localInput(Date.now()+3*864e5)}" required><div class="notice">The organizer collects funds when every spot is filled. Otherwise participants can claim refunds after the deadline. Creating a plan does not deposit your share.</div><p class="error" id="form-error" role="alert"></p><button class="primary full" type="submit">Create practice plan →</button></form>`,'START SOMETHING GOOD');$('#create-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);try{const p=validatePlan({id:crypto.randomUUID(),title:f.get('title').trim(),location:f.get('location').trim(),category:f.get('category'),amount:Number(f.get('amount')),target:Number(f.get('target')),deadline:new Date(f.get('deadline')).getTime(),eventAt:new Date(f.get('eventAt')).getTime(),ownerId:state.user.id,ownerName:state.user.name,members:[],ledger:[],cancelled:false,released:false});state.plans.unshift(p);save();filter='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.remove('active'));render();showPlan(p.id);toast('Plan created. Ready for your crew.')}catch(e){$('#form-error').textContent=e.message}}}
$('#create').onclick=create;$('#new-plan').onclick=create;
$('#how').onclick=()=>modal('<h2>Good plans. Clear rules.</h2><p><b>1. Set the plan.</b> Choose the activity, exact group size, contribution, and funding deadline.</p><p><b>2. Everyone commits.</b> Each person deposits the same amount. A deposit stays committed while the plan is open.</p><p><b>3. Confirm or refund.</b> Fill every spot before the deadline and the organizer can collect the money. If the target is missed, each person can claim their deposit back.</p><div class="notice">This build uses local demo credits. Real group synchronization, Monad settlement, and easy sign-in are not connected yet. There is no actual venue booking.</div>','HOW IT WORKS');
$('#about-demo').onclick=()=>modal('<h2>A safe place to try the flow.</h2><p>All plans, people, deposits, and refunds here are practice data saved in this browser. No wallet is connected and no money moves.</p><p>Use “Practice controls” inside an open plan to add demo friends or pass its deadline. Invitation copying generates text only; it does not share a live balance.</p><p>The planned onchain version will enforce funding and refund rules through a contract. This prototype is not yet the hackathon-ready settlement implementation.</p>','ABOUT THIS BUILD');
$('#profile').onclick=()=>{modal(`<h2>What should we call you?</h2><form id="profile-form"><label for="display-name">Display name</label><input id="display-name" maxlength="30" required value="${esc(state.user.name)}"><button class="primary full">Save name</button></form>`);$('#profile-form').onsubmit=e=>{e.preventDefault();const name=$('#display-name').value.trim();if(!name)return;state.user.name=name;for(const p of state.plans){if(p.ownerId===state.user.id)p.ownerName=name;const m=p.members.find(m=>m.id===state.user.id);if(m)m.name=name}save();render();close();toast('Name updated.')}};
$('#reset').onclick=()=>{modal('<h2>Start fresh?</h2><p>This removes your local practice plans and restores the three examples.</p><button id="confirm-reset" class="primary full">Reset practice data</button>');$('#confirm-reset').onclick=()=>{state=seed();save();filter='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.remove('active'));render();close();toast('Practice data reset.')}};
setInterval(()=>{render();if(activeId&&$('#modal').open&&$('#share-plan'))showPlan(activeId)},30000);
save();render();
